// Only trigger once; mark element to avoid re-clicks
if (element.dataset.autoClicked) return;
const href = element.getAttribute('href');
if (!href || href === '#') return;
element.dataset.autoClicked = '1';
// Navigate to the English results URL automatically
window.location.href = href;

element.style.display = 'inline-block';
element.style.marginTop = '10px';
element.style.padding = '8px 16px';
element.style.backgroundColor = '#1a73e8';
element.style.color = '#fff';
element.style.fontWeight = 'bold';
element.style.fontSize = '14px';
element.style.borderRadius = '4px';
element.style.textDecoration = 'none';
element.style.lineHeight = '20px';
element.style.boxShadow = '0 1px 3px rgba(0,0,0,0.3)';
element.textContent = '🌐 Change to English';
